def parse_countries(raw: str) -> list[str]:
    return [c.strip().upper() for c in raw.split(",") if c.strip()]


def discover_jrc_industry_countries(jrc_root: Path) -> list[str]:
    pattern = re.compile(r"Industry_([A-Z]{2})\.xlsx$", re.IGNORECASE)
    countries: set[str] = set()
    for path in jrc_root.rglob("*Industry_*.xlsx"):
        match = pattern.search(path.name)
        if match:
            countries.add(match.group(1).upper())
    if not countries:
        raise FileNotFoundError(f"No JRC-IDEES industry workbooks found under {jrc_root}")
    return sorted(countries)


def resolve_countries(requested: list[str], sources: dict[str, Path | None]) -> list[str]:
    aliases = {"ALL", "EU", "EUROPE"}
    if not any(c in aliases for c in requested):
        return requested

    jrc_countries = discover_jrc_industry_countries(sources["jrc_root"])
    runnable: list[str] = []
    skipped: list[str] = []
    for country in jrc_countries:
        try:
            find_secures_demand_csv(sources["secures_root"], country)
        except FileNotFoundError:
            skipped.append(country)
        else:
            runnable.append(country)

    if skipped:
        print(f"Skipping countries without matching SECURES demand CSV: {','.join(skipped)}", flush=True)
    if not runnable:
        raise FileNotFoundError("No countries have both JRC-IDEES industry workbooks and SECURES demand profiles.")
    print(f"Resolved countries from JRC-IDEES and SECURES: {','.join(runnable)}", flush=True)
    return runnable



def materialize_helpers(refresh: bool = False) -> dict[str, Path]:
    """Extract embedded helper scripts and return their runtime paths."""
    HELPER_DIR.mkdir(parents=True, exist_ok=True)
    paths: dict[str, Path] = {}
    for name, payload in HELPER_SOURCES.items():
        path = HELPER_DIR / name
        if refresh or not path.exists():
            path.write_bytes(gzip.decompress(base64.b64decode(payload)))
        paths[name] = path
    return paths

def download_file(url: str, out_path: Path, refresh: bool = False) -> Path:
    if out_path.exists() and not refresh:
        print(f"Using cached source: {out_path}", flush=True)
        return out_path
    out_path.parent.mkdir(parents=True, exist_ok=True)
    print(f"Downloading {url}", flush=True)
    print(f"  -> {out_path}", flush=True)
    req = urllib.request.Request(url, headers={"User-Agent": "h2res-industry-builder/1.0"})
    partial = out_path.with_name(out_path.name + ".part")
    with urllib.request.urlopen(req, timeout=180) as response:
        with open(partial, "wb") as fh:
            shutil.copyfileobj(response, fh, length=1024 * 1024)
    partial.replace(out_path)
    return out_path


def extract_zip(zip_path: Path, out_dir: Path, refresh: bool = False) -> Path:
    marker = out_dir / ".extracted"
    if marker.exists() and not refresh:
        print(f"Using extracted cache: {out_dir}", flush=True)
        return out_dir
    if out_dir.exists() and refresh:
        shutil.rmtree(out_dir)
    out_dir.mkdir(parents=True, exist_ok=True)
    print(f"Extracting {zip_path} -> {out_dir}", flush=True)
    with zipfile.ZipFile(zip_path) as zf:
        zf.extractall(out_dir)
    marker.write_text("ok\n", encoding="utf-8")
    return out_dir


def download_and_extract(url: str | None, zip_path: Path, out_dir: Path, refresh: bool) -> Path | None:
    if not url:
        return None
    download_file(url, zip_path, refresh=refresh)
    return extract_zip(zip_path, out_dir, refresh=refresh)


def find_jrc_industry_xlsx(jrc_root: Path, country: str) -> Path:
    for pattern in [f"JRC-IDEES-2021_Industry_{country}.xlsx", f"*Industry_{country}.xlsx"]:
        matches = sorted(jrc_root.rglob(pattern))
        if matches:
            return matches[0]
    raise FileNotFoundError(f"JRC-IDEES industry workbook not found for {country} under {jrc_root}")


def find_secures_demand_csv(secures_root: Path, country: str) -> Path:
    for pattern in [
        f"Demand_{country}_scenDN_ALL_1_ERA5-Land.csv",
        f"*Demand_{country}*ERA5-Land*.csv",
        f"*{country}*scenDN*.csv",
    ]:
        matches = sorted(secures_root.rglob(pattern))
        if matches:
            return matches[0]
    raise FileNotFoundError(f"SECURES demand CSV not found for {country} under {secures_root}")


