def run(cmd: list[object]) -> None:
    clean = [str(x) for x in cmd if str(x)]
    print(" ".join(f'"{x}"' if " " in x else x for x in clean), flush=True)
    subprocess.run(clean, check=True)


def clean_dir(path: Path) -> None:
    if path.exists():
        shutil.rmtree(path)
    path.mkdir(parents=True, exist_ok=True)


def validate_outputs(final_dir: Path) -> None:
    units = final_dir / UNITS_FILE
    dist = final_dir / DIST_FILE
    if not units.exists() or not dist.exists():
        raise FileNotFoundError(f"Expected outputs missing in {final_dir}")
    u = pd.read_csv(units, nrows=5)
    d = pd.read_csv(dist, nrows=5)
    print(f"Validated units: {units} ({len(u.columns)} columns)", flush=True)
    print(f"Validated distributions: {dist} ({len(d.columns)} columns)", flush=True)


def model_industry_name(value: object, keep_heat_categories: bool = False) -> str:
    """Convert JRC labels to the identifiers used by the H2RES Industry_data sheet."""
    text = industry_label(value)
    category = industry_category(value)
    return f"{text}[{category}]" if keep_heat_categories and category != "all" else text


def _max_shares(shares: dict[str, float]) -> dict[str, float]:
    """Numeric equivalent of the substitution formulae in the legacy workbook."""
    out = dict(shares)
    fossil_switchable = sum(shares.get(f, 0.0) for f in (
        "Coal", "Gas", "Oil", "LPG", "diesel", "fuel_oil", "kerosene", "petrol", "waste"
    ))
    out["Electricity"] = max(shares.get("Electricity", 0.0), 0.5)
    out["DME"] = shares.get("DME", 0.0) + shares.get("fuel_oil", 0.0)
    out["H2"] = shares.get("H2", 0.0) + fossil_switchable
    out["Hydrogen"] = shares.get("Hydrogen", 0.0) + fossil_switchable
    out["ammonia"] = out["H2"]
    out["e_diesel"] = shares.get("e_diesel", 0.0) + shares.get("diesel", 0.0)
    out["e_kerosene"] = shares.get("e_kerosene", 0.0) + shares.get("kerosene", 0.0)
    out["e_methane"] = shares.get("e_methane", 0.0) + shares.get("Gas", 0.0)
    out["lignin"] = shares.get("lignin", 0.0) + shares.get("bitumen", 0.0)
    out["methanol"] = shares.get("methanol", 0.0) + shares.get("petrol", 0.0)
    out["heat"] = shares.get("heat", 0.0) * 1.5
    return {fuel: min(1.0, max(0.0, float(value))) for fuel, value in out.items()}


def write_model_ready_industry_data(
    units_path: Path,
    out_dir: Path,
    keep_heat_categories: bool = False,
    include_efuels: bool = True,
    output_name: str = INDUSTRY_DATA_FILE,
    write_workbook: bool = True,
) -> pd.DataFrame:
    src = pd.read_csv(units_path)
    src = src[src["fuel_type"].isin(FUEL_DEFAULTS)].copy()
    if not include_efuels:
        src = src[~src["fuel_type"].isin(EFUEL_FUELS - {"H2"})].copy()
    # Adapt unsupported fuels before aggregating categories so the regular and
    # category variants represent exactly the same service and fuel quantities.
    src["category"] = src["Industry"].map(industry_category)
    src["Industry"] = src["Industry"].map(industry_label)
    for col in ("cap_mw", "share_fuel_2020"):
        src[col] = pd.to_numeric(src[col], errors="coerce").fillna(0.0)
    cf = {"Gas": .85, "Coal": .85, "Biomass": .85, "Electricity": 1.0,
          "diesel": .85, "fuel_oil": .85, "LPG": .85, "kerosene": .85,
          "bitumen": .85, "heat": 1.0, "waste": .85,
          "Oil": .85, "Hydrogen": 1.0, "non_energy": .85,
          "non_energy_gas": .85, "non_energy_oil": .85}
    src["energy_weight"] = src.apply(
        lambda r: r["cap_mw"] * cf.get(r["fuel_type"], 1.0)
        * FUEL_DEFAULTS[r["fuel_type"]][2], axis=1
    )

    defaults = dict(FUEL_DEFAULTS)
    if not include_efuels:
        src["fuel_type"] = src["fuel_type"].replace(REGULAR_FUELS)
        defaults = {f: FUEL_DEFAULTS[f] for f in ("Gas", "Coal", "Biomass", "Electricity")}
        defaults.update({
            "Oil": ("Oil_industry", "Oil", .99, .4, "Y"),
            "Hydrogen": ("Hydrogen_industry", "Hydrogen", .99, 0, "Y"),
            "non_energy": ("non_energy_industry", "non_energy", .99, 0, "Y"),
        })
    keys = ["System", "zone", "Industry", "category", "fuel_type"]
    grouped = src.groupby(keys, as_index=False).agg(
        cap_mw=("cap_mw", "sum"),
        energy_weight=("energy_weight", "sum"),
    )
    if not include_efuels:
        from industry.fuel_representation import redistribute_service_mix
        records, audit = [], []
        block_keys = keys[:-1]
        local_keys = ["System", "zone", "Industry"]
        fallback = grouped.groupby(local_keys + ["fuel_type"]).energy_weight.sum()
        for key, block in grouped.groupby(block_keys, sort=False):
            original = block.set_index("fuel_type")
            amounts = original.energy_weight.to_dict()
            adjusted, notes = redistribute_service_mix(amounts, fallback.loc[key[:3]].to_dict())
            for fuel, amount in adjusted.items():
                before = amounts.get(fuel, 0.)
                capacity = float(original.at[fuel, "cap_mw"]) if fuel in original.index else 0.
                capacity += (amount - before) / (cf.get(fuel, .85) * defaults[fuel][2])
                records.append(dict(zip(block_keys, key), fuel_type=fuel, cap_mw=capacity, energy_weight=amount))
            audit.extend(dict(zip(block_keys, key), **note,
                              service_weight_unit="annual_useful_MWh_divided_by_8760") for note in notes)
        grouped = pd.DataFrame(records, columns=keys + ["cap_mw", "energy_weight"])
        pd.DataFrame(audit, columns=block_keys + ["method", "recipient_fuel", "source_heat_weight",
            "source_waste_weight", "recipient_fraction", "added_service_weight", "basis",
            "service_weight_unit"]).to_csv(out_dir / (Path(output_name).stem + "_fuel_redistribution.csv"), index=False)
    if not keep_heat_categories:
        grouped["category"] = "all"
        grouped = grouped.groupby(keys, as_index=False)[["cap_mw", "energy_weight"]].sum()
    totals = grouped.groupby(["System", "zone", "Industry", "category"])["energy_weight"].transform("sum")
    grouped["share_fuel_2020"] = grouped["energy_weight"].div(totals.where(totals > 0)).fillna(0.0)

    rows: list[dict[str, object]] = []
    block_keys = ["System", "zone", "Industry", "category"]
    lookup = grouped.set_index(keys)
    for system, zone, industry, category in grouped[block_keys].drop_duplicates().itertuples(index=False):
        shares: dict[str, float] = {}
        caps: dict[str, float] = {}
        active_fuels = list(defaults)
        for fuel in active_fuels:
            key = (system, zone, industry, category, fuel)
            if key in lookup.index:
                item = lookup.loc[key]
                shares[fuel] = float(item["share_fuel_2020"])
                caps[fuel] = float(item["cap_mw"])
            else:
                shares[fuel] = caps[fuel] = 0.0
        maxima = _max_shares(shares)
        for fuel in active_fuels:
            unit, group, efficiency, co2, include = defaults[fuel]
            row = dict.fromkeys(INDUSTRY_DATA_COLUMNS)
            row.update({
                "System": system, "zone": zone, "Industry": industry, "category": category,
                "unit_name": unit, "fuel_type": fuel, "group": group,
                "efficiency": efficiency, "CO2Intensity": co2, "fossil": "Y" if co2 else "N",
                "include_in_the_model": include, "cap_mw": caps[fuel],
                "max_cap": max(5000, caps[fuel]), "decom_start_existing_cap": 8,
                "life_time": 15, "decom_start_new": 10, "final_life_cap": 0.1,
                "share_fuel_2020": shares[fuel],
                "max_share_fuel": maxima.get(fuel, shares[fuel]),
                "max_inv_period": 1000 if include_efuels or keep_heat_categories else 10000,
                **CAPTURE_DEFAULTS,
            })
            rows.append(row)
    result = annual_limits(pd.DataFrame(rows, columns=INDUSTRY_DATA_COLUMNS))
    result.to_csv(out_dir / output_name, index=False)
    if write_workbook:
        with pd.ExcelWriter(out_dir / INDUSTRY_WORKBOOK_FILE, engine="openpyxl") as writer:
            result.to_excel(writer, sheet_name="Industry_data", index=False)
        print(f"Model-ready workbook: {out_dir / INDUSTRY_WORKBOOK_FILE}", flush=True)
    print(f"Model-ready Industry_data: {out_dir / output_name}", flush=True)
    return result


def write_industry_variants(units_path: Path, out_dir: Path, efuels_selected: bool, keep_heat_categories: bool = False) -> None:
    """Write regular/e-fuel tables with and without process-heat categories."""
    variants = {
        "regular": write_model_ready_industry_data(
            units_path, out_dir, False, False, INDUSTRY_VARIANT_FILES["regular"], False
        ),
        "efuels": write_model_ready_industry_data(
            units_path, out_dir, False, True, INDUSTRY_VARIANT_FILES["efuels"], False
        ),
        "regular_heat": write_model_ready_industry_data(
            units_path, out_dir, True, False, INDUSTRY_VARIANT_FILES["regular_heat"], False
        ),
        "efuels_heat": write_model_ready_industry_data(
            units_path, out_dir, True, True, INDUSTRY_VARIANT_FILES["efuels_heat"], False
        ),
    }
    selected_key = ("efuels" if efuels_selected else "regular") + ("_heat" if keep_heat_categories else "")
    selected = variants[selected_key]
    selected_heat = variants["efuels_heat" if efuels_selected else "regular_heat"]
    selected.to_csv(out_dir / INDUSTRY_DATA_FILE, index=False)
    selected_heat.to_csv(out_dir / "Industry_data_heat_categories.csv", index=False)
    from industry.fuel_representation import REGULAR_FUEL_METHOD
    (out_dir / "industry_fuel_representation.json").write_text(json.dumps({
        "method": REGULAR_FUEL_METHOD,
        "unsupported_regular_fuels": ["heat", "waste"],
        "conserved": "regional industry/category useful-service weights and hourly demand",
        "historical_electricity": "observed electricity subtraction retained; reassigned service is additional modeled demand",
        "audits": [Path(INDUSTRY_VARIANT_FILES[name]).stem + "_fuel_redistribution.csv" for name in ("regular", "regular_heat")],
    }, indent=2), encoding="utf-8")
    with pd.ExcelWriter(out_dir / INDUSTRY_WORKBOOK_FILE, engine="openpyxl") as writer:
        selected.to_excel(writer, sheet_name="Industry_data", index=False)
        variants["regular"].to_excel(writer, sheet_name="Industry_regular", index=False)
        variants["efuels"].to_excel(writer, sheet_name="Industry_efuels", index=False)
        variants["regular_heat"].to_excel(writer, sheet_name="Regular_heat_categories", index=False)
        variants["efuels_heat"].to_excel(writer, sheet_name="Efuels_heat_categories", index=False)
    print(
        f"Industry variants written; canonical mode={'efuels' if efuels_selected else 'regular'}: "
        f"{out_dir / INDUSTRY_WORKBOOK_FILE}", flush=True
    )


def write_demand_views(hourly_path: Path, out_dir: Path) -> None:
    """Write explicit total-demand and process-heat views from the SECURES curves."""
    data = pd.read_csv(hourly_path)
    id_cols = [c for c in ("period", "System", "zone") if c in data.columns]
    category_cols = [c for c in data.columns if c not in id_cols and c != "all"]
    overall = data[id_cols].copy()
    overall["all"] = data[category_cols].sum(axis=1)
    overall.to_csv(out_dir / OVERALL_DIST_FILE, index=False)

    # The reader calls all useful industrial energy "heat", including NON_HEAT.
    # Keep the separate process-heat-only view below for existing consumers.
    categories = data[id_cols].copy()
    sectors_all: dict[str, list[str]] = {}
    for col in category_cols:
        name = model_industry_name(col, keep_heat_categories=True)
        if name in categories:
            categories[name] += pd.to_numeric(data[col], errors="raise")
        else:
            categories[name] = pd.to_numeric(data[col], errors="raise")
        sectors_all.setdefault(industry_label(col), []).append(col)
    categories["all"] = categories.drop(columns=id_cols).sum(axis=1)
    categories.to_csv(out_dir / "industry_category_profiles.csv", index=False)
    units = pd.read_csv(out_dir / INDUSTRY_VARIANT_FILES["efuels_heat"])
    electric = units.loc[units.fuel_type.eq("Electricity")].copy()
    electricity = data[id_cols].copy()
    electricity["Power"] = 0.0
    for row in electric.itertuples(index=False):
        column = f"{row.Industry}[{row.category}]"
        selected = data.System.eq(row.System) & data.zone.eq(row.zone)
        if column in categories:
            electricity.loc[selected, "Power"] += (
                categories.loc[selected, column] * float(row.share_fuel_2020) / float(row.efficiency)
            )
    electricity = electricity.pivot(index="period", columns="zone", values="Power").reset_index()
    electricity.to_csv(out_dir / "industry_electricity.csv", index=False)
    model_heat = data[id_cols].copy()
    for sector, cols in sectors_all.items():
        model_heat[sector] = data[cols].sum(axis=1)
    model_heat["all"] = model_heat[list(sectors_all)].sum(axis=1)
    model_heat.to_csv(out_dir / "industry_heat.csv", index=False)

    heat_cols = [c for c in category_cols if "[NON_HEAT]" not in c]
    heat = data[id_cols].copy()
    sectors: dict[str, list[str]] = {}
    for col in heat_cols:
        sector = model_industry_name(col, keep_heat_categories=False)
        sectors.setdefault(sector, []).append(col)
    for sector, cols in sectors.items():
        heat[sector] = data[cols].sum(axis=1)
    heat.insert(len(id_cols), "all", heat[list(sectors)].sum(axis=1))
    heat.to_csv(out_dir / HEAT_DIST_FILE, index=False)
    print(f"Overall industry demand distribution: {out_dir / OVERALL_DIST_FILE}", flush=True)
    print(f"Process-heat industry distribution: {out_dir / HEAT_DIST_FILE}", flush=True)


def build_country(args: argparse.Namespace, country: str, sources: dict[str, Path | None]) -> Path:
    country = country.upper()
    country_root = args.out_root / country
    alloc_dir = country_root / "01_allocated"
    base_dir = country_root / "02_units_hourly"
    final_dir = country_root / "03_non_energy"
    if args.clean:
        clean_dir(country_root)
    alloc_dir.mkdir(parents=True, exist_ok=True)
    base_dir.mkdir(parents=True, exist_ok=True)
    final_dir.mkdir(parents=True, exist_ok=True)

    jrc_xlsx = find_jrc_industry_xlsx(sources["jrc_root"], country)
    secures_csv = find_secures_demand_csv(sources["secures_root"], country)
    iep_dir = sources["iep_dir"] or args.empty_facility_dir
    iep_dir.mkdir(parents=True, exist_ok=True)

    helpers = materialize_helpers(refresh=args.refresh_helpers)
    allocate_script = helpers["allocate_nuts3_sector_fuel_JRC_tempbins_v4_14.py"]
    generate_script = helpers["generate_from_allocated_JRC_tempbins_fixed_v10.py"]
    postprocess_script = helpers["postprocess_chem_non_energy_from_jrc_v7.py"]

    alloc_cmd = [
        sys.executable, allocate_script,
        "--nuts3", sources["nuts3"],
        "--nuts3-col", "NUTS_ID",
        "--nuts-level", args.nuts_level,
        "--country", country,
        "--year", args.year,
        "--jrc-xlsx", jrc_xlsx,
        "--iep-dir", iep_dir,
        "--out-dir", alloc_dir,
        "--temp-bins",
    ]
    # Regional raster reconciliation is performed below, with explicit fuel
    # mappings and national margins. The embedded helper supplies JRC/site data.
    alloc_cmd.append("--skip-eigl")
    if sources["eutl_dir"]:
        alloc_cmd += ["--eutl-dir", sources["eutl_dir"]]
    if args.debug:
        alloc_cmd.append("--debug")
    run(alloc_cmd)

    # The embedded allocator extracts the JRC margins and optional facilities.
    # Reconcile with rebased raster shares before creating units/hourly demand.
    from industry.regional_allocation import reconcile_allocation
    allocation = reconcile_allocation(
        alloc_dir, sources["nuts3"], country, args.nuts_level,
        None if args.skip_eigl else sources["eigl_dir"], args.eigl_year,
        equal=args.regional_allocation == "equal",
        facility_cache=args.data_dir / "facility_sources", year=args.year,
        download=args.download_sources, refresh=args.refresh_sources,
    )
    allocation["national_energy_year"] = args.year
    import json
    (alloc_dir / "regional_allocation.json").write_text(json.dumps(allocation, indent=2), encoding="utf-8")

    run([
        sys.executable, generate_script,
        "--alloc-csv", alloc_dir / "allocated_nuts_sector_category_fuel.csv",
        "--secures-csv", secures_csv,
        "--secures-year", args.secures_year,
        "--out-dir", base_dir,
        "--reserve", args.reserve,
        "--tech-template", sources["tech_template"],
        "--tech-cf", TECH_CF,
        "--write-stacked",
    ] + (["--debug"] if args.debug else []))

    post_cmd = [
        sys.executable, postprocess_script,
        "--units", base_dir / "industry_units_by_category_ALL.csv",
        "--jrc-xlsx", jrc_xlsx,
        "--jrc-year", args.year,
        "--out-units", final_dir / UNITS_FILE,
        "--hourly", base_dir / "industry_hourly_distributions_by_category_ALL.csv",
        "--out-hourly", final_dir / DIST_FILE,
        "--tech-cf", TECH_CF,
    ]
    if args.adjust_hourly:
        post_cmd.append("--adjust-hourly")
    if args.debug:
        post_cmd.append("--debug")
    run(post_cmd)

    write_industry_variants(final_dir / UNITS_FILE, final_dir, args.efuels, args.keep_heat_categories)
    write_demand_views(final_dir / DIST_FILE, final_dir)
    validate_outputs(final_dir)
    return final_dir


def combine_countries(final_dirs: list[Path], out_dir: Path) -> None:
    out_dir.mkdir(parents=True, exist_ok=True)
    if len(final_dirs) == 1:
        # The country files already contain all selected regions and variants.
        # Rewriting the same multi-million-cell inspection workbook is costly.
        names = [UNITS_FILE, DIST_FILE, INDUSTRY_DATA_FILE, "Industry_data_heat_categories.csv",
                 *INDUSTRY_VARIANT_FILES.values(), INDUSTRY_WORKBOOK_FILE,
                 HEAT_DIST_FILE, OVERALL_DIST_FILE, "industry_heat.csv",
                 "industry_category_profiles.csv", "industry_electricity.csv", "industry_fuel_representation.json",
                 *(Path(INDUSTRY_VARIANT_FILES[key]).stem + "_fuel_redistribution.csv" for key in ("regular", "regular_heat"))]
        for name in names:
            shutil.copy2(final_dirs[0] / name, out_dir / name)
        from industry.regional_allocation import write_generation_provenance
        write_generation_provenance(final_dirs, out_dir)
        print(f"Combined model-ready workbook: {out_dir / INDUSTRY_WORKBOOK_FILE}", flush=True)
        return
    units_frames = [pd.read_csv(d / UNITS_FILE) for d in final_dirs]
    dist_frames = [pd.read_csv(d / DIST_FILE) for d in final_dirs]
    pd.concat(units_frames, ignore_index=True).to_csv(out_dir / UNITS_FILE, index=False, quoting=csv.QUOTE_MINIMAL)
    pd.concat(dist_frames, ignore_index=True).to_csv(out_dir / DIST_FILE, index=False, quoting=csv.QUOTE_MINIMAL)
    variant_names = [INDUSTRY_DATA_FILE, "Industry_data_heat_categories.csv", *INDUSTRY_VARIANT_FILES.values()]
    combined_variants = {
        name: pd.concat([pd.read_csv(d / name) for d in final_dirs], ignore_index=True)
        for name in variant_names
    }
    for name, frame in combined_variants.items():
        frame.to_csv(out_dir / name, index=False)
    with pd.ExcelWriter(out_dir / INDUSTRY_WORKBOOK_FILE, engine="openpyxl") as writer:
        combined_variants[INDUSTRY_DATA_FILE].to_excel(writer, sheet_name="Industry_data", index=False)
        combined_variants[INDUSTRY_VARIANT_FILES["regular"]].to_excel(writer, sheet_name="Industry_regular", index=False)
        combined_variants[INDUSTRY_VARIANT_FILES["efuels"]].to_excel(writer, sheet_name="Industry_efuels", index=False)
        combined_variants[INDUSTRY_VARIANT_FILES["regular_heat"]].to_excel(writer, sheet_name="Regular_heat_categories", index=False)
        combined_variants[INDUSTRY_VARIANT_FILES["efuels_heat"]].to_excel(writer, sheet_name="Efuels_heat_categories", index=False)
    for name in (HEAT_DIST_FILE, OVERALL_DIST_FILE, "industry_heat.csv", "industry_category_profiles.csv"):
        pd.concat([pd.read_csv(d / name) for d in final_dirs], ignore_index=True).to_csv(
            out_dir / name, index=False
        )
    electricity = pd.concat([pd.read_csv(d / "industry_electricity.csv").set_index("period") for d in final_dirs], axis=1)
    if electricity.columns.duplicated().any():
        raise ValueError("Industry model zones must be globally unique across countries")
    electricity.reset_index().to_csv(out_dir / "industry_electricity.csv", index=False)
    for key in ("regular", "regular_heat"):
        name = Path(INDUSTRY_VARIANT_FILES[key]).stem + "_fuel_redistribution.csv"
        pd.concat([pd.read_csv(d / name) for d in final_dirs], ignore_index=True).to_csv(out_dir / name, index=False)
    shutil.copy2(final_dirs[0] / "industry_fuel_representation.json", out_dir / "industry_fuel_representation.json")
    print(f"Combined units: {out_dir / UNITS_FILE}", flush=True)
    print(f"Combined distributions: {out_dir / DIST_FILE}", flush=True)
    print(f"Combined model-ready workbook: {out_dir / INDUSTRY_WORKBOOK_FILE}", flush=True)
    from industry.regional_allocation import write_generation_provenance
    write_generation_provenance(final_dirs, out_dir)


def prepare_sources(args: argparse.Namespace) -> dict[str, Path | None]:
    args.out_root.mkdir(parents=True, exist_ok=True)
    args.data_dir.mkdir(parents=True, exist_ok=True)
    args.empty_facility_dir.mkdir(parents=True, exist_ok=True)

    nuts3 = args.nuts3 or args.data_dir / "NUTS_RG_20M_2021_4326_LEVL_3.geojson"
    if args.download_sources:
        download_file(args.nuts3_url, nuts3, refresh=args.refresh_sources)

    jrc_root = args.jrc_root
    if jrc_root is None:
        jrc_zip = args.data_dir / "JRC-IDEES-2021.zip"
        jrc_root = args.data_dir / "JRC-IDEES-2021"
        if args.download_sources:
            download_file(args.jrc_idees_url, jrc_zip, refresh=args.refresh_sources)
            extract_zip(jrc_zip, jrc_root, refresh=args.refresh_sources)

    secures_root = args.secures_root
    if secures_root is None:
        secures_zip = args.data_dir / "Hourly_profiles_ERA5-Land_1981-2010.zip"
        secures_root = args.data_dir / "SECURES_ERA5_Land_1981_2010"
        if args.download_sources:
            download_file(args.secures_url, secures_zip, refresh=args.refresh_sources)
            extract_zip(secures_zip, secures_root, refresh=args.refresh_sources)

    iep_dir = args.iep_dir or download_and_extract(args.iep_zip_url, args.data_dir / "iep_industrial_reporting.zip", args.data_dir / "IEP", args.refresh_sources)
    eutl_dir = args.eutl_dir or download_and_extract(args.eutl_zip_url, args.data_dir / "eutl.zip", args.data_dir / "EUTL", args.refresh_sources)
    eigl_dir = args.eigl_dir or download_and_extract(args.eigl_zip_url, args.data_dir / "eigl.zip", args.data_dir / "EIGL", args.refresh_sources)
    from industry.regional_allocation import EIGL_URL, EIGL_YEAR, RASTER_FUELS
    args.eigl_year = args.eigl_year or EIGL_YEAR

    tech_template = args.tech_template or args.data_dir / "industry_tech_template_internal.xlsx"
    ensure_tech_template(tech_template)

    for label, path in [("NUTS3", nuts3), ("JRC-IDEES root", jrc_root), ("SECURES root", secures_root), ("tech template", tech_template)]:
        if path is None or not Path(path).exists():
            raise FileNotFoundError(f"{label} source not found: {path}")

    return {
        "nuts3": Path(nuts3),
        "jrc_root": Path(jrc_root),
        "secures_root": Path(secures_root),
        "iep_dir": Path(iep_dir) if iep_dir else None,
        "eutl_dir": Path(eutl_dir) if eutl_dir else None,
        "eigl_dir": Path(eigl_dir) if eigl_dir else None,
        "tech_template": Path(tech_template),
    }


def build_parser() -> argparse.ArgumentParser:
    p = argparse.ArgumentParser(description="Generate H2RES industry unit tables and hourly demand distributions.")
    p.add_argument("--countries", type=parse_countries, default=parse_countries("HR"), help="Comma-separated ISO2 list, e.g. HR,SI,IT, or ALL/EU to run every country found in JRC-IDEES with SECURES profiles")
    p.add_argument("--year", type=int, default=2019)
    p.add_argument("--secures-year", type=int, default=2010)
    p.add_argument("--nuts-level", type=int, default=3, choices=[0, 1, 2, 3])
    p.add_argument("--reserve", type=float, default=0.15)
    p.add_argument("--out-root", type=Path, default=RUN_DIR)
    p.add_argument("--data-dir", type=Path, default=DATA_DIR)
    p.add_argument("--empty-facility-dir", type=Path, default=DATA_DIR / "empty_facility_proxy")
    p.add_argument("--clean", action=argparse.BooleanOptionalAction, default=True)
    p.add_argument("--debug", action="store_true")
    p.add_argument("--adjust-hourly", action=argparse.BooleanOptionalAction, default=True,
                   help="Apply the paper's hourly feedstock correction when moving demand between temperature categories")
    p.add_argument(
        "--keep-heat-categories", action="store_true",
        help="Keep temperature bands in Industry_data; default aggregates to the sector-level shape used by the legacy workbook.",
    )
    p.add_argument(
        "--efuels", action=argparse.BooleanOptionalAction, default=False,
        help="Use the e-fuel-compatible table as canonical Industry_data. All regular/e-fuel and heat-category variants are always written.",
    )
    p.add_argument("--refresh-helpers", action="store_true", help="Rewrite embedded helper scripts before running.")

    p.add_argument("--download-sources", action=argparse.BooleanOptionalAction, default=True)
    p.add_argument("--refresh-sources", action="store_true")
    p.add_argument("--nuts3-url", default=NUTS_URL)
    p.add_argument("--jrc-idees-url", default=JRC_IDEES_URL)
    p.add_argument("--secures-url", default=SECURES_URL)
    p.add_argument("--iep-zip-url", default=None)
    p.add_argument("--eutl-zip-url", default=None)
    p.add_argument("--eigl-zip-url", default=None)

    p.add_argument("--nuts3", type=Path, default=None)
    p.add_argument("--jrc-root", type=Path, default=None)
    p.add_argument("--secures-root", type=Path, default=None)
    p.add_argument("--iep-dir", type=Path, default=None)
    p.add_argument("--eutl-dir", type=Path, default=None)
    p.add_argument("--eigl-dir", type=Path, default=None)
    p.add_argument("--eigl-year", default=None)
    p.add_argument("--skip-eigl", action=argparse.BooleanOptionalAction, default=False)
    p.add_argument("--regional-allocation", choices=("require-weights", "equal"), default="require-weights",
                   help="Use EIGL/facility geography; equal is an explicit regional proxy assumption")
    p.add_argument("--tech-template", type=Path, default=None)
    return p


def main(argv: Iterable[str] | None = None) -> int:
    parser = build_parser()
    args = parser.parse_args(list(argv) if argv is not None else None)
    try:
        sources = prepare_sources(args)
        countries = resolve_countries(args.countries, sources)
        final_dirs = [build_country(args, c, sources) for c in countries]
        combine_countries(final_dirs, args.out_root / "combined")
    except (FileNotFoundError, ValueError, subprocess.CalledProcessError, zipfile.BadZipFile) as exc:
        print(f"ERROR: {exc}", file=sys.stderr)
        return 2
    return 0


if __name__ == "__main__":
    raise SystemExit(main())
